mapper.select:
SELECT p.state policy_state,d.state directory_state,p.desired_epoch,p.applied_epoch FROM auth_governance.policy_partition p
JOIN auth_governance.directory_fence d ON d.tenant_id=p.tenant_id
WHERE p.tenant_id=#{p.tenantId} AND p.application_id=#{p.applicationId} AND p.environment=#{p.environment}

SELECT id,target_issuer,target_subject,member_kind,expires_at::text,membership_valid_to::text,state,version FROM auth_governance.invitation
WHERE tenant_id=#{a.tenantId} AND operator_ref=#{a.operatorRef} AND sponsor_membership_id=#{a.sponsorMembershipId} AND id > #{after}
ORDER BY id LIMIT 101
